// AuroraRevit v1.8.3 educational template: Find Unconnected Duct Ends
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_DuctCurves);
    var ducts = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_DuctCurves).WhereElementIsNotElementType().ToElements();
    var openDucts = ducts.Where(x => (x as MEPCurve)?.ConnectorManager?.Connectors.Cast<Connector>().Any(c => !c.IsConnected) == true).ToList();
}

