// AuroraRevit v1.8.3 educational template: Create an MEP Coordination 3D View
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_DuctCurves);
    var viewType = new FilteredElementCollector(doc).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().FirstOrDefault(x => x.ViewFamily == ViewFamily.ThreeDimensional);
    if (viewType == null) return;
    var view = View3D.CreateIsometric(doc, viewType.Id);
    view.Name = "MEP Coordination";
}

